window.DATA={"meta":{"title":"L'ultima festa di Vic Lombardo","subtitle":"Cena con delitto · Long Island, 1926","kicker":"Long Island · 1926","icon":"🥂","host":"vic","voices":{"n":"","v":"Vic Lombardo","a":"Ambrogio"}},"pub":{"tony":{"name":"Tony","g":"m","img":"img/p-tony.jpg?v=2","partner":"noemi","title":"L'Asso dei Cieli","costume":"Giubbotto di pelle da aviatore, sciarpa bianca, occhialoni, maschera dorata, sigaro","dress":"una giacca di pelle o un giubbotto, una sciarpa bianca e, se ce l'hai, un sigaro finto ✈️","blurb":"Aviatore, eroe dei giornali: ha quasi attraversato l'Atlantico. In realtà il suo aereo vola soprattutto di notte. Sempre attaccato al telefono: a ogni festa si fa passare New York da Ambrogio. Fuma solo sigari cubani. Deve a Vic un mucchio di soldi."},"noemi":{"name":"Noemi","g":"f","img":"img/p-noemi.jpg?v=2","partner":"tony","title":"La Regina della Roulette","costume":"Abito di paillettes nero e oro, fascia con piuma, braccialetti, fiches","dress":"un vestito luccicante, una fascia tra i capelli e tanti braccialetti 🎰","blurb":"Croupier del casinò segreto di Vic, nella serra della villa. Bellissima e monella: fa girare la roulette e la testa a tutti. Al suo tavolo si prendono le fiches e le Aurora, le sigarette della casa: lei non fuma, ma si ricorda chi prende cosa. Vic ha un debole per lei, e non lo nasconde."},"francesca":{"name":"Francesca","g":"f","img":"img/p-francesca.jpg?v=2","partner":"simone","title":"La Grande Illusionista","costume":"Cilindro, frac, mantello, bacchetta, trucco metà oro e metà argento","dress":"un cappello (meglio un cilindro), un foulard e, se ti va, un trucco metà oro e metà argento 🎩","blurb":"Illusionista dei teatri di Broadway: fa sparire colombe, collane e mariti. Vic l'ha pagata per il gran numero di mezzanotte. Il suo umore cambia come la luna: o è raggiante, o è nera come la notte. E quando si lamenta… si lamenta con Simone."},"simone":{"name":"Simone","g":"m","img":"img/p-simone.jpg?v=2","partner":"francesca","title":"Il Meccanico","costume":"Tuta da officina, occhialoni da corsa, maschera nera da domino, chiave inglese","dress":"una camicia con le maniche arrotolate, le bretelle e una mascherina nera 🔧","blurb":"Ex pilota di corse, oggi il meccanico di Vic: tiene in vita la Rolls-Royce e prepara i fuochi d'artificio di mezzanotte. Fortissimo, ma appena si siede si addormenta, anche dentro un'auto. Non fuma: «con la benzina addosso, mai»."},"lorenzo":{"name":"Lorenzo","g":"m","img":"img/p-lorenzo.jpg?v=2","partner":"claudia","title":"Il Pittore","costume":"Basco, occhiali tondi, giacca macchiata di colore, maschera nera da domino, pennello","dress":"un basco o una sciarpa, occhiali tondi se li hai e una mascherina nera 🎨","blurb":"Pittore squattrinato: da un mese è ospite alla villa per dipingere il ritratto di Vic. Parla poco, osserva tutto e ha sempre le mani sporche di colore."},"claudia":{"name":"Claudia","g":"f","img":"img/p-claudia.jpg?v=2","partner":"lorenzo","title":"La Scrittrice","costume":"Abito di velluto nero, orecchie da gatta, baffi disegnati, bocchino, taccuino","dress":"qualcosa di nero e due baffi da gatta disegnati 🐈‍⬛","blurb":"Scrittrice di romanzi gialli. Ogni martedì Vic le racconta la sua vita per un libro di memorie: lei ascolta, prende appunti e legge le persone come libri aperti. Fuma sigarette turche col bocchino."}},"npc":{"vic":{"name":"Vic Lombardo","img":"img/n-vic.jpg?v=2","blurb":"61 anni, il Re del Gin. Partito da Lentini a 14 anni con una valigia di cartone, oggi è l'uomo più ricco della costa. Generoso, malinconico, vendicativo. Non fuma da vent'anni e non sopporta il fumo."},"ambrogio":{"name":"Ambrogio","img":"img/n-ambrogio.jpg?v=2","blurb":"Il maggiordomo. 70 anni, siciliano, da trent'anni con Vic. In guerra faceva l'infermiere. Senza occhiali non vede a un metro."}},"facts":["21:00 — Cena e ballo in maschera. Vic: «A mezzanotte, a luci spente, farò un annuncio che cambierà la vita di tutti voi».","23:15 — Vic sale nello studio della torre. Ambrogio gli porta gin, un secchiello di ghiaccio e il punteruolo.","23:15–23:58 — La festa continua: maschere, charleston, gente che va e viene.","23:58 — Ambrogio spegne tutte le luci della villa per i fuochi d'artificio.","00:00 — Fuochi sul mare. Dalla torre si sente uno sparo.","00:06 — Torna la luce. 00:10 — Ambrogio trova Vic morto."],"vote":{"suspects":["tony","noemi","francesca","simone","lorenzo","claudia","ambrogio"],"questions":[{"id":"killer","q":"Chi ha ucciso Vic Lombardo?","pts":3},{"id":"book","q":"Chi ha rubato il libro nero?","pts":1},{"id":"gun","q":"Chi ha nascosto la pistola nel pianoforte?","pts":1},{"id":"actor","q":"Miglior attore/attrice della serata (non tu)","pts":0,"players":true}]},"topic":"ufv-myk09qafciza","scene":{"villa":"img/s-villa.jpg?v=2","cena":"img/s-cena.jpg?v=2"},"p":{"0c763c868e614f9b":"","6a4b5e53484ed3fc":"","ad24df94c1a2d576":"","66fdc398a5cfe489":"","e20e43a0ef4cfa22":"","9d6444758436c653":""},"h":{"f0e5767fa8b09519":""},"v":1793486577574};
